// SPDX-License-Identifier: MIT
pragma solidity 0.8.7;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/RebaseDividendToken.sol";

contract MockFactory {
    function createPair(address, address) external returns (address) {
        return address(0x123);
    }
}

contract MockRouter {
    address public factory;

    constructor(address _factory) {
        factory = _factory;
    }

    function WETH() external pure returns (address) {
        return address(0x55d398326f99059fF775485246999027B3197955);
    }
}

contract WhitelistDuplicationTest is Test {
    RebaseDividendToken token;
    address owner = address(0x1);
    address user1 = address(0x2);
    address constant ROUTER_ADDRESS = 0x10ED43C718714eb63d5aA57B78B54704E256024E;

    function setUp() public {
        // Deploy mocks and set up router
        MockFactory mockFactory = new MockFactory();
        MockRouter mockRouter = new MockRouter(address(mockFactory));

        bytes memory mockRouterCode = address(mockRouter).code;
        vm.etch(ROUTER_ADDRESS, mockRouterCode);

        // Set storage slot 0 in router to contain mock factory address
        vm.store(
            ROUTER_ADDRESS,
            bytes32(0),
            bytes32(uint256(uint160(address(mockFactory))))
        );

        vm.startPrank(owner);
        token = new RebaseDividendToken();
        vm.stopPrank();
    }

    function testWhitelistDuplication() public {
        // Prepare address array
        address[] memory accounts = new address[](1);
        accounts[0] = user1;

        // Initially add user
        vm.prank(owner);
        token.addWhitelist(accounts);

        // Verify initial whitelist state
        address[] memory initialList = token.whitelistedUsers();
        assertEq(initialList.length, 1, "Initial whitelist count mismatch");
        assertEq(initialList[0], user1, "User not in initial whitelist");

        // Remove user
        vm.prank(owner);
        token.removeWhitelist(accounts);

        // Re-add the same user - should cause duplication
        vm.prank(owner);
        token.addWhitelist(accounts);

        // Verify duplicate entry
        address[] memory updatedList = token.whitelistedUsers();
        assertEq(updatedList.length, 2, "Duplicate entry not created");
        assertEq(updatedList[0], user1, "First user mismatch");
        assertEq(updatedList[1], user1, "Second user mismatch - not duplicate");
    }
}
